<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
$pdo=kd_db();header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
$tokenId=null;$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');$path=(string)($_SERVER['REQUEST_URI']??'/api.php');
$respond=static function(int $status,array $payload)use($pdo,&$tokenId,$method,$path):never{if($tokenId!==null){try{$pdo->prepare('INSERT INTO api_request_logs (token_id,method,request_path,ip_address,status_code,created_at) VALUES (?,?,?,?,?,NOW())')->execute([$tokenId,$method,mb_substr($path,0,500),$_SERVER['REMOTE_ADDR']??null,$status]);}catch(Throwable $e){error_log('API log: '.$e->getMessage());}}http_response_code($status);echo json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;};
if($method==='OPTIONS'){http_response_code(204);exit;}
$auth=(string)($_SERVER['HTTP_AUTHORIZATION']??'');if(!$auth&&function_exists('getallheaders')){$headers=getallheaders();$auth=(string)($headers['Authorization']??$headers['authorization']??'');}
if(!preg_match('/^Bearer\s+([A-Za-z0-9_-]{30,})$/',$auth,$match))$respond(401,['success'=>false,'error'=>'Bearer API anahtarı gerekli.']);
$hash=hash('sha256',$match[1]);$q=$pdo->prepare('SELECT * FROM api_tokens WHERE token_hash=? AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at>NOW())');$q->execute([$hash]);$token=$q->fetch();if(!$token)$respond(401,['success'=>false,'error'=>'API anahtarı geçersiz veya süresi dolmuş.']);$tokenId=(int)$token['id'];
$q=$pdo->prepare('SELECT COUNT(*) FROM api_request_logs WHERE token_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 1 MINUTE)');$q->execute([$tokenId]);if((int)$q->fetchColumn()>=120)$respond(429,['success'=>false,'error'=>'İstek limiti aşıldı.']);
$pdo->prepare('UPDATE api_tokens SET last_used_at=NOW() WHERE id=?')->execute([$tokenId]);$scopes=json_decode($token['scopes_json'],true)?:[];$resource=(string)($_GET['resource']??'');
$requireScope=static function(string $scope)use($scopes,$respond):void{if(!in_array($scope,$scopes,true))$respond(403,['success'=>false,'error'=>'Bu API anahtarında gerekli yetki bulunmuyor: '.$scope]);};
$limit=max(1,min(100,(int)($_GET['limit']??50)));
if($resource==='products'&&$method==='GET'){$requireScope('products:read');$rows=$pdo->query("SELECT id,name,sku,description,sale_price,purchase_price,stock_quantity,unit,status FROM products WHERE status='active' ORDER BY id DESC LIMIT ".$limit)->fetchAll();$respond(200,['success'=>true,'data'=>$rows]);}
if($resource==='customers'&&$method==='GET'){$requireScope('customers:read');$rows=$pdo->query("SELECT id,name,email,phone,status,created_at FROM customers ORDER BY id DESC LIMIT ".$limit)->fetchAll();$respond(200,['success'=>true,'data'=>$rows]);}
if($resource==='orders'&&$method==='GET'){$requireScope('orders:read');$rows=$pdo->query("SELECT id,order_number,customer_id,status,payment_status,subtotal,tax_total,discount_total,grand_total,currency,created_at FROM orders ORDER BY id DESC LIMIT ".$limit)->fetchAll();$respond(200,['success'=>true,'data'=>$rows]);}
if($resource==='orders'&&$method==='POST'){$requireScope('orders:write');$body=json_decode((string)file_get_contents('php://input'),true);if(!is_array($body))$respond(400,['success'=>false,'error'=>'JSON gövdesi geçersiz.']);$customerId=(int)($body['customer_id']??0);$itemsIn=$body['items']??[];if(!is_array($itemsIn)||!$itemsIn||count($itemsIn)>100)$respond(422,['success'=>false,'error'=>'En az bir sipariş kalemi gerekli.']);$q=$pdo->prepare("SELECT id FROM customers WHERE id=? AND status='active'");$q->execute([$customerId]);if(!$q->fetchColumn())$respond(422,['success'=>false,'error'=>'Aktif müşteri bulunamadı.']);$items=[];$sub=0;$tax=0;foreach($itemsIn as $line){$pid=(int)($line['product_id']??0);$qty=(float)($line['quantity']??0);$q=$pdo->prepare("SELECT id,name,sku,sale_price,tax_rate,stock_quantity,track_stock FROM products WHERE id=? AND status='active'");$q->execute([$pid]);$p=$q->fetch();if(!$p||$qty<=0||$qty>100000)$respond(422,['success'=>false,'error'=>'Ürün veya miktar geçersiz.']);if((int)$p['track_stock']&&(float)$p['stock_quantity']<$qty)$respond(409,['success'=>false,'error'=>'Yetersiz stok: '.$p['name']]);$lineSub=round($qty*(float)$p['sale_price'],2);$lineTax=round($lineSub*(float)$p['tax_rate']/100,2);$items[]=[$p,$qty,$lineSub,$lineTax];$sub+=$lineSub;$tax+=$lineTax;}
try{$pdo->beginTransaction();$tmp='TMP-'.bin2hex(random_bytes(8));$total=$sub+$tax;$pdo->prepare("INSERT INTO orders (order_number,customer_id,status,subtotal,tax_total,discount_total,grand_total,coupon_code,order_source,payment_method,payment_status,currency,notes,created_at) VALUES (?,?,'draft',?,?,0,?,NULL,'api','api','pending','TRY',?,NOW())")->execute([$tmp,$customerId,$sub,$tax,$total,trim((string)($body['notes']??''))?:'API siparişi']);$orderId=(int)$pdo->lastInsertId();$number='API-'.date('Y').'-'.str_pad((string)$orderId,6,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE orders SET order_number=? WHERE id=?')->execute([$number,$orderId]);$ins=$pdo->prepare('INSERT INTO order_items (order_id,product_id,product_name,sku,quantity,unit_price,tax_rate,line_subtotal,line_tax,line_total,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,NOW())');foreach($items as [$p,$qty,$lineSub,$lineTax])$ins->execute([$orderId,$p['id'],$p['name'],$p['sku'],$qty,$p['sale_price'],$p['tax_rate'],$lineSub,$lineTax,$lineSub+$lineTax]);$pdo->prepare('INSERT INTO order_status_history (order_id,user_id,from_status,to_status,note,created_at) VALUES (?,NULL,NULL,?,?,NOW())')->execute([$orderId,'draft','API üzerinden oluşturuldu']);$pdo->commit();\KodVadAll\Core\WebhookService::enqueue($pdo,'order.created',['id'=>$orderId,'order_number'=>$number,'grand_total'=>$total]);$respond(201,['success'=>true,'data'=>['id'=>$orderId,'order_number'=>$number,'status'=>'draft','grand_total'=>$total,'currency'=>'TRY']]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('API order create: '.$e->getMessage());$respond(500,['success'=>false,'error'=>'Sipariş oluşturulamadı.']);}}
$respond(404,['success'=>false,'error'=>'API kaynağı veya yöntem bulunamadı.']);
